sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '' || newValue === oldValue) {
        return;
    }
    // Convert 'string dates' into 'JavaScript Date objects'
    var selectedDate = new Date(newValue);
    var today = new Date();
    // Reset today's time to midnight
    today.setHours(0, 0, 0, 0);

    // If the selected date is in the past, warn the user and clear the field
    if (selectedDate < today) {
        g_form.showFieldMsg('start_time', 'Error: Trip Start Date cannot be in the past!', 'error');
        g_form.clearValue('start_time');
		g_form.clearValue('end_time');
    }
}
